import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, list_contacts
from src.service import add_contact, import_contacts
from src.api import handle_add, handle_import

def fresh():
    c = sqlite3.connect(":memory:")
    initialize(c)
    return c

c = fresh()
assert import_contacts(c, []) == {"inserted": 0, "updated": 0}
assert import_contacts(c, [{"email": "  A@B.com ", "name": " Ann "}]) == {"inserted": 1, "updated": 0}
assert list_contacts(c) == [("a@b.com", "Ann")]
assert import_contacts(c, [{"email": "a@b.com", "name": "Ann"}, {"email": "x@y", "name": "X"}]) == {"inserted": 1, "updated": 1}
assert list_contacts(c) == [("a@b.com", "Ann"), ("x@y", "X")]

bad_batches = [
    [{"email": "a@b", "name": "A"}, "junk"],
    [{"email": "a@b", "name": "A", "extra": 1}],
    [{"email": "a@b"}],
    [{"email": "a@@b", "name": "A"}],
    [{"email": "@b", "name": "A"}],
    [{"email": "a@", "name": "A"}],
    [{"email": "a b@c", "name": "A"}],
    [{"email": "a@b", "name": "   "}],
    [{"email": "a@b", "name": "A"}, {"email": "A@B", "name": "B"}],
    [{"email": "ok@x", "name": "Ok"}, {"email": "bad", "name": "B"}],
    [{"email": 1, "name": "A"}],
]
for batch in bad_batches:
    try:
        import_contacts(c, batch)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for {batch}")
assert list_contacts(c) == [("a@b.com", "Ann"), ("x@y", "X")]

for bad in [None, {"contacts": "x"}, {"contacts": [], "x": 1}, [], {}]:
    try:
        handle_import(c, bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for envelope {bad!r}")

assert handle_import(c, {"contacts": [{"email": "n@m", "name": "N"}]}) == {"inserted": 1, "updated": 0}

class FailingConn:
    def __init__(self, real):
        self.real = real
        self.n = 0
    def execute(self, sql, *a):
        if sql.startswith("INSERT"):
            self.n += 1
            if self.n == 2:
                raise sqlite3.OperationalError("boom")
        return self.real.execute(sql, *a)
    def commit(self): return self.real.commit()
    def rollback(self): return self.real.rollback()

before = list_contacts(c)
try:
    import_contacts(FailingConn(c), [{"email": "p@q", "name": "P"}, {"email": "r@s", "name": "R"}])
except sqlite3.OperationalError:
    pass
else:
    raise AssertionError("expected db failure")
assert list_contacts(c) == before

assert add_contact(c, "z@z", "Z") is None
assert ("z@z", "Z") in list_contacts(c)
print("import checks ok")
